"use strict";
const test=require("node:test");const assert=require("node:assert/strict");const {buildAnchor,validateAnchor,selectNextTask,appendHistoryEntry}=require("../bootstrap-context");const {selectActiveProjectAndPlan}=require("../active-plan");
test("builds five sourced blocks",()=>{const a=validateAnchor(buildAnchor());assert.deepEqual(a.blocks.map(x=>x.id),["architecture","roadmap","flow","rules","nextStep"]);for(const b of a.blocks)assert.ok(b.sources.length);});
test("uses active CMS plan in planning blocks",()=>{const a=buildAnchor();for(const id of ["roadmap","flow","nextStep"]){const b=a.blocks.find(x=>x.id===id);assert.ok(b.sources.includes("site-context/registry/plans/PLAN-EDITORIAL-CMS-MVP.json"));assert.ok(!b.sources.some(x=>x.includes("PLAN-ANCHOR-MVP")));}});
test("represents awaiting authorization without operational command",()=>{const selected=selectActiveProjectAndPlan();assert.equal(selected.activeProject.id,"EPIC-004");assert.equal(selected.executionState,"awaiting_next_authorization");const activeTasks=selected.plan.phases.flatMap(x=>x.tasks||[]).filter(x=>x.status==="in_progress");assert.equal(activeTasks.length,0);const a=buildAnchor();const n=a.blocks.find(x=>x.id==="nextStep").content;assert.equal(n.task,"AWAITING-NEXT-AUTHORIZATION");assert.equal(n.command,null);});
test("selects in_progress before planned and returns null command when absent",()=>{const p={currentPhase:"P",phases:[{id:"P",tasks:[{id:"A",status:"planned"},{id:"B",status:"in_progress"}]}]};assert.equal(selectNextTask(p).id,"B");assert.equal(selectNextTask({currentPhase:"P",phases:[{id:"P",tasks:[]}]}),null);});
test("preserves previousHash chain",()=>{const h={entries:[{hash:"prior"}]};const a={generatedAt:"now",blocks:[{content:{currentProject:{id:"EPIC"},currentPhase:{id:"PHASE"}}}]};appendHistoryEntry(h,a,"current");assert.equal(h.entries[1].previousHash,"prior");});